CREATE COLUMN TABLE "TEST_AP"."@RA_CONN" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_PWD" NCLOB MEMORY THRESHOLD 1000, "U_TOKEN" NCLOB MEMORY THRESHOLD 1000, "U_USER" NVARCHAR(254), "U_ServerName" NVARCHAR(254), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KRA_CONN_NAME" ON "TEST_AP"."@RA_CONN" ( "Name" ASC )